import logging

from utils.logger import create_logger

logger = create_logger(logging.DEBUG)


class Solution:
    def sumGame(self, num: str) -> bool:
        n = len(num)
        n_by_2 = n // 2

        num_holes_in_first_half = sum(c == "?" for c in num[:n_by_2])
        sum_of_first_half = sum(int(c) if c != "?" else 0 for c in num[:n_by_2])
        num_holes_in_second_half = sum(c == "?" for c in num[n_by_2:])
        sum_of_second_half = sum(int(c) if c != "?" else 0 for c in num[n_by_2:])

        # If Alice has the last turn, then she'll definitely win.
        num_turns_left = num_holes_in_first_half + num_holes_in_second_half
        if num_turns_left % 2 != 0:
            logger.debug("Alice has the last turn, so she wins.")
            return True

        sum_difference = sum_of_first_half - sum_of_second_half
        logger.debug(
            f"Initially, num_holes_in_first_half={num_holes_in_first_half}, num_holes_in_second_half={num_holes_in_second_half}, sum_difference={sum_difference}"
        )

        # Simplified solution from others on leetcode.
        return sum_difference != (
            9 * (num_holes_in_second_half - num_holes_in_first_half) // 2
        )

        turn = 0  # 0 means Alice, 1 means Bob.
        i = 0

        while num_turns_left > 0:
            # logger.debug(f"i = {i:05} ...")

            # Each hole has a potential value in range [0,9]
            # sum_of_first_half <= final_sum_of_first_half <= sum_of_first_half + 9 * num_holes_in_first_half
            # sum_of_second_half <= final_sum_of_second_half <= sum_of_second_half + 9 * num_holes_in_second_half
            final_sum_difference_range = [
                sum_difference
                - 9 * (num_holes_in_first_half + num_holes_in_second_half),
                sum_difference
                + 9 * (num_holes_in_first_half + num_holes_in_second_half),
            ]
            # logger.debug(f"  final_sum_difference_range = {final_sum_difference_range}")
            if not (
                final_sum_difference_range[0] <= 0 <= final_sum_difference_range[1]
            ):
                # logger.debug(f"  not (final_sum_difference_range[0] <= 0 <= final_sum_difference_range[1])")
                logger.debug("  Returning true as sum ranges are too far apart.")
                return True
            # if Bob has the last turn, then Bob will win if sum( side without the whole ) <= the sum( side with the whole ) <= sum( side without the whole ) - 9
            if num_turns_left == 1:
                logger.debug(
                    f"  Final turn. This must be Bob's turn. abs(sum_difference) = {abs(sum_difference)}"
                )
                return abs(sum_difference) > 9
            if (
                num_holes_in_first_half == num_holes_in_second_half
                and sum_difference == 0
            ):
                logger.debug(
                    "  At this point, number of holes is equal on both side and sum_difference = 0"
                )
                return False
            if (
                num_turns_left == 2
                and (num_holes_in_first_half * num_holes_in_second_half) == 0
            ):
                if (num_holes_in_first_half == 2 and sum_difference == -9) or (
                    num_holes_in_second_half == 2 and sum_difference == 9
                ):
                    logger.debug(
                        "  At this point, there are two more turns left and the remaining sum difference = 9."
                    )
                    return False
                else:
                    logger.debug(
                        "  At this point, there are two more turns left and the remaining sum difference != 9."
                    )
                    return True

            # handle this turn..
            if turn == 0:
                # Alice's turn. She'll try to maximize the difference between the two halves.
                # logger.debug(f"  Alice's turn")
                if sum_difference >= 0:
                    if num_holes_in_first_half > 0:
                        num_holes_in_first_half -= 1
                        sum_difference += 9
                    else:
                        num_holes_in_second_half -= 1
                        sum_difference -= 0
                else:
                    if num_holes_in_second_half > 0:
                        num_holes_in_second_half -= 1
                        sum_difference -= 9
                    else:
                        num_holes_in_first_half -= 1
                        sum_difference += 0
            else:
                # Bob's turn. He'll try to minimize the difference between the two halves.
                # logger.debug(f"  Bob's turn")
                if sum_difference >= 0:
                    if num_holes_in_second_half > 0:
                        num_holes_in_second_half -= 1
                        sum_difference -= min(9, sum_difference)
                    else:
                        num_holes_in_first_half -= 1
                        sum_difference += 0
                else:
                    if num_holes_in_first_half > 0:
                        num_holes_in_first_half -= 1
                        sum_difference += min(9, -sum_difference)
                    else:
                        num_holes_in_second_half -= 1
                        sum_difference -= 0

            # logger.debug(f"  After turn, num_holes_in_first_half={num_holes_in_first_half}, num_holes_in_second_half={num_holes_in_second_half}, sum_difference={sum_difference}")
            turn = 1 - turn
            i += 1
            num_turns_left -= 1

        return sum_of_first_half != sum_of_second_half


