@pretty_test_runner(time_limit_in_sec=0.025, stop_on_tc_failure=False)
def Test(num: str, expected: bool) -> tuple[bool, str]:
    actual = Solution().sumGame(num)
    if actual != expected:
        return False, f"got={actual}, wanted={expected}"
    return True, ""


